for loc,c in copy.items():
    other='en' if loc=='ja' else 'ja'
    refs=f'<ul><li><a href="{official}">KHK · 第二種販売主任者</a></li><li><a href="https://goldbook.iupac.org/terms/view/F02494">IUPAC · fraction</a></li><li><a href="https://goldbook.iupac.org/terms/view/S06021/pdf">IUPAC · stoichiometric</a></li></ul>'
    demo=f'<section class="example"><p class="eyebrow">{esc(c["demo"])}</p><label for="case">{esc(c["select"])}</label><select id="case">'+''.join(f'<option value="{i}">{esc(t)}</option>' for i,t in enumerate(c['options']))+'</select><dl aria-live="polite">'+''.join(f'<div><dt>{esc(c[key])}</dt><dd id="{key}">—</dd></div>' for key in ['basis','amount','oxygen','normalized','carbon','water'])+f'</dl><p class="muted">{esc(c["caution"])}</p></section><script src="{base}/assets/example.js" defer></script>'
    home=f'<section class="hero"><div><p class="eyebrow">LPG / JAPANESE STUDY</p><h1>{esc(c["hero"]).replace(chr(10),"<br>")}</h1><p class="lede">{esc(c["intro"])}</p><p class="badge">{esc(c["status"])}</p><p class="muted">{esc(c["language"])}</p><a class="button" href="{url(loc,"guide")}">{esc(c["learn"])}</a></div><aside><img src="{base}/assets/icon.svg" width="170" height="170" alt=""><strong>C3H8 + C4H10</strong><span>mol% / mass%</span><p>44g/mol ·58g/mol</p></aside></section><div class="callout">{esc(c["candidate"])}</div>'+demo+f'<section><h2>{esc(c["offline"])}</h2><p>{esc(c["offlinebody"])}</p></section>'
    guide=''.join(f'<section id="{t["id"]}"><p class="eyebrow">{i:02d} / CONCEPT</p><h2>{esc(t[loc+"Title"])}</h2><p>{esc(t[loc+"Body"])}</p></section>' for i,t in enumerate(brief['guideTopics'],1))
    bodies={'home':home,'guide':guide+f'<h2>{esc(c["source"])}</h2>'+refs,'features':'<ul class="cards">'+''.join('<li>'+esc(t)+'</li>' for t in c['featuretext'])+'</ul><div class="callout">'+esc(c['candidate'])+'</div>','how-to':'<ol>'+''.join('<li>'+esc(s)+'</li>' for s in c['flow'])+'</ol><p>'+esc(c['local'])+'</p>','exam':'<p>'+esc(c['examtext'])+'</p>'+refs,'faq':''.join('<section><h2>'+esc(q)+'</h2><p>'+esc(a)+'</p></section>' for q,a in c['faqitems']),'support':'<p>'+esc(c['help'])+'</p><p>'+esc(c['local'])+'</p><p><a class="button" href="mailto:june1012june@gmail.com">RushLabs · june1012june@gmail.com</a></p>','privacy':'<p>'+esc(c['privacytext'])+'</p><p>'+esc(c['appprivacy'])+'</p><p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a></p><p>RushLabs · <a href="mailto:june1012june@gmail.com">june1012june@gmail.com</a></p>','terms':'<p>'+esc(c['termstext'])+'</p><p>'+esc(c['local'])+'</p>'}
    for route,body in bodies.items():
        title=c['name'] if route=='home' else c[keys[route]]+' · '+c['name']
        description=c['intro'] if route=='home' else c[keys[route]]+' — '+c['language']
        canonical=url(loc,route)
        structured={'@context':'https://schema.org','@type':'WebPage','name':title,'url':canonical,'inLanguage':loc,'description':description}
        nav=''.join(f'<a href="{url(loc,k)}">{esc(c[keys[k]])}</a>' for k in ['guide','features','support'])
        footer=''.join(f'<a href="{url(loc,k)}">{esc(c[keys[k]])}</a>' for k in routes)
        head=f'<!doctype html><html lang="{loc}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="ja" href="{url("ja",route)}"><link rel="alternate" hreflang="en" href="{url("en",route)}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{base}/assets/icon-1024.png"><link rel="icon" href="{base}/assets/icon.svg"><link rel="stylesheet" href="{base}/assets/style.css"><script type="application/ld+json">{json.dumps(structured,ensure_ascii=False)}</script></head>'
        content=f'<body><a class="skip" href="#main">{esc(c["skip"])}</a><header><a class="brand" href="{url(loc,"home")}"><img src="{base}/assets/icon.svg" alt="" width="46" height="46"><span>{esc(c["name"])}</span></a><nav aria-label="Navigation">{nav}<a lang="{other}" href="{url(other,route)}">{c["other"]}</a></nav></header><main id="main">'
        if route!='home':content+='<article><h1>'+esc(c[keys[route]])+'</h1>'
        content+=body.replace("組成ノート",'<span class="nowrap">組成ノート</span>')
        if route!='home':content+='</article>'
        content+=f'<section class="scope"><h2>{esc(c["model"])}</h2><p>{esc(c["limits"])}</p><p>{esc(c["notice"])}</p></section></main><footer><p>{esc(c["language"])}</p><nav>{footer}</nav><p>©2026 RushLabs · {esc(c["updated"])}</p></footer></body></html>'
        current=loc if route=='home' else loc+'/'+route
        def local_link(m):
            target=m.group(2)
            relative=posixpath.relpath(target or '.',current)
            if target.endswith('/'):relative+='/'
            return m.group(1)+relative+'"'
        content=re.sub(r'((?:href|src)=")'+re.escape(base)+r'/([^"]*)"',local_link,content)
        assets=('../' if route=='home' else '../../')+'assets/'
        head=head.replace(f'href="{base}/assets/icon.svg"',f'href="{assets}icon.svg"').replace(f'href="{base}/assets/style.css"',f'href="{assets}style.css"')
        head=head.replace(f'<html lang="{loc}">',f'<html lang="{loc}" translate="no">').replace('<head>','<head><meta name="google" content="notranslate">',1)
        out=D/loc/('index.html' if route=='home' else route+'/index.html');out.parent.mkdir(parents=True,exist_ok=True);out.write_text(head+content)

